\section{Introduction}

\subsection{Partial cubes and their cuts}
The $n$-dimensional hypercube $Q_n$ has vertex set $\{0,1\}^n$ with edges joining
vertices that differ in exactly one coordinate; its graph distance is the Hamming
distance. A \emph{partial cube} is a connected graph admitting an isometric
embedding into some hypercube. Partial cubes appear across discrete geometry
(regions of hyperplane and pseudoline arrangements), order theory (linear
extensions and the Boolean lattice), theoretical computer science (state spaces of
chip-firing games), and mathematical psychology (media theory).

We work in the \emph{coordinate model}. Fix a finite coordinate set $\alpha$. A
\emph{sign vector} is a function $v : \alpha \to \{\tru,\fls\}$, i.e.\ a vertex of
the hypercube on $\alpha$; a finite family of vertices is a finite set
$V \subseteq \{\tru,\fls\}^{\alpha}$. Each coordinate $i \in \alpha$ induces a
\emph{cut} separating $V$ into two \emph{opposite semicubes}
\[
\Semi{V}{i}{\tru} = \{ v \in V : v_i = \tru \}, \qquad
\Semi{V}{i}{\fls} = \{ v \in V : v_i = \fls \}.
\]
In the Djokovi\'c--Winkler theory these cuts are the $\Theta$-classes and the two
semicubes are the halfspaces they bound.

\subsection{The invariant}

\begin{definition}[balanced coordinate; harmonic-even]
A coordinate $i$ is \emph{balanced} in $V$ if
$\lvert \Semi{V}{i}{\tru}\rvert = \lvert \Semi{V}{i}{\fls}\rvert$. The set $V$ is
\emph{harmonic-even} if every coordinate is balanced.
\end{definition}

The terminology reflects the discrete analogy with the mean-value (harmonic)
property: harmonic-evenness asserts that every cut halves the total mass.

\begin{definition}[opposite-semicube Helly property]
$V$ satisfies the \emph{opposite-semicube Helly property} if for every coordinate
$i$ there is a bijection $\Semi{V}{i}{\tru} \simeq \Semi{V}{i}{\fls}$; each cut
admits a matching between its two sides.
\end{definition}

\subsection{Contributions}
We prove: (1) the opposite-semicube Helly property is equivalent to
harmonic-evenness (Theorem~\ref{thm:equiv}); (2) antipodal closure implies
harmonic-evenness with the antipode as explicit matching, whence the full
hypercube is harmonic-even (Theorem~\ref{thm:mirror}, Corollary~\ref{cor:univ});
(3) harmonic-evenness forces an even vertex count over a nonempty coordinate set
(Theorem~\ref{thm:parity}); (4) harmonic-evenness is multiplicative across
arbitrary finite Cartesian products (Theorems~\ref{thm:prodbal}
and~\ref{thm:prodhelly}), recovering the classical two-factor statement
(Corollary~\ref{cor:binary}).

\section{Preliminaries}
Throughout $\alpha$ is a finite coordinate set and
$V \subseteq \{\tru,\fls\}^{\alpha}$ is finite; $\Semi{V}{i}{b}$ denotes the
semicube of coordinate $i$ with sign $b$. We use: (i) two finite sets admit a
bijection iff they have equal cardinality; and (ii) the two-fiber decomposition
\begin{equation}\label{eq:fiber}
|V| = \lvert \Semi{V}{i}{\tru}\rvert + \lvert \Semi{V}{i}{\fls}\rvert
\qquad \text{for every } i.
\end{equation}

\section{The matching--balance equivalence}

\begin{theorem}[Matching--Balance Equivalence]\label{thm:equiv}
For any finite $V$, the opposite-semicube Helly property holds if and only if $V$
is harmonic-even.
\end{theorem}

\begin{proof}[Proof sketch]
Both directions use that a bijection between finite sets exists iff their
cardinalities agree. Given a bijection $\Semi{V}{i}{\tru}\simeq\Semi{V}{i}{\fls}$,
transporting cardinalities gives balance of $i$; conversely, balance provides
equal cardinalities and hence a bijection. Quantifying over $i$ gives the
equivalence.
\end{proof}

\section{A canonical matching from antipodal symmetry}

\begin{definition}[antipode]
The \emph{antipodal involution} is the coordinatewise complement
$(\antip\,v)_i = \lnot\,v_i$. It satisfies $\antip(\antip\,v)=v$ and is injective.
\end{definition}

\begin{definition}[antipodal closure]
$V$ is \emph{antipodally closed} if $v\in V \Rightarrow \antip\,v \in V$.
\end{definition}

\begin{lemma}[semicube exchange]\label{lem:exchange}
If $V$ is antipodally closed then for every coordinate $i$,
$\Semi{V}{i}{\fls} = \antip\bigl(\Semi{V}{i}{\tru}\bigr)$.
\end{lemma}

\begin{proof}[Proof sketch]
If $v\in V$ with $v_i=\tru$ then $\antip\,v\in V$ by closure and
$(\antip\,v)_i=\fls$, so the antipode maps $\Semi{V}{i}{\tru}$ into
$\Semi{V}{i}{\fls}$; the involution property gives the reverse inclusion.
\end{proof}

\begin{theorem}[Canonical Mirror]\label{thm:mirror}
If $V$ is antipodally closed then $V$ is harmonic-even, and the antipodal
involution is an explicit fixed-point-free matching of every cut.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:exchange}, $\Semi{V}{i}{\fls}$ is the injective image of
$\Semi{V}{i}{\tru}$ under the antipode, so the two semicubes are equinumerous;
hence every coordinate is balanced. No sign vector equals its own complement, so
the antipode is fixed-point-free.
\end{proof}

\begin{lemma}\label{lem:univclosed}
The full hypercube $\{\tru,\fls\}^{\alpha}$ is antipodally closed.
\end{lemma}

\begin{corollary}\label{cor:univ}
The full hypercube is harmonic-even: every cut halves it, matched by the antipode.
\end{corollary}

\section{Parity of the vertex count}

\begin{theorem}[Parity Obstruction]\label{thm:parity}
If $\alpha$ is nonempty and $V$ is harmonic-even then $|V|$ is even.
\end{theorem}

\begin{proof}[Proof sketch]
Pick any $i\in\alpha$. Balance gives
$\lvert\Semi{V}{i}{\tru}\rvert=\lvert\Semi{V}{i}{\fls}\rvert$, and
\eqref{eq:fiber} gives $|V| = 2\,\lvert\Semi{V}{i}{\tru}\rvert$.
\end{proof}

\begin{corollary}\label{cor:singleton}
A singleton is never harmonic-even over a nonempty coordinate set: its unique cut
is maximally unbalanced and $1$ is odd.
\end{corollary}

\section{The finite-family product law}

\subsection{The product construction}
Let $\iota$ be a finite index type and, for each $k\in\iota$, let
$V_k\subseteq\{\tru,\fls\}^{\beta_k}$ be a partial cube. The Cartesian product
lives on the disjoint-union coordinate set
$\Sigma_k\beta_k=\{\langle k,i\rangle : k\in\iota,\ i\in\beta_k\}$.

\begin{definition}[merge map and product cube]
The merge map assembles a family into a single sign vector,
$\operatorname{merge}(f)\langle k,i\rangle = f_k(i)$, and is injective. With
$\prod_k V_k$ the set of families $(f_k)$, $f_k\in V_k$, define
$\prod^{\square}_k V_k = \operatorname{merge}\bigl(\prod_k V_k\bigr)$.
A coordinate of the product is a pair $\langle k,i\rangle$ with $i$ a coordinate of
$V_k$.
\end{definition}

\subsection{The semicube cardinality formula}

\begin{lemma}[slice identity]\label{lem:slice}
For a coordinate $\langle k,i\rangle$ and sign $c$,
\[
\Bigl\{ f\in\textstyle\prod_j V_j : f_k(i)=c \Bigr\}
= \prod_j V_j', \quad V_k'=\Semi{V_k}{i}{c},\ V_j'=V_j\ (j\neq k).
\]
\end{lemma}

\begin{lemma}[product semicube cardinality]\label{lem:prodcard}
For every $\langle k,i\rangle$ and $c$,
\[
\Bigl\lvert \Semi{\textstyle\prod^{\square}_j V_j}{\langle k,i\rangle}{c}\Bigr\rvert
= \lvert \Semi{V_k}{i}{c}\rvert \cdot \prod_{j\neq k} |V_j| .
\]
\end{lemma}

\begin{proof}[Proof sketch]
The product's semicube is the merge image of the slice in
Lemma~\ref{lem:slice}; injectivity of merge preserves cardinality, and the
cardinality of a product of finite families is the product of cardinalities.
Isolating the $k$-th factor (now $\Semi{V_k}{i}{c}$) from the untouched remaining
factors gives the formula.
\end{proof}

\subsection{Multiplicativity}

\begin{theorem}[Product Balance Law]\label{thm:prodbal}
Let $(V_k)_{k\in\iota}$ be a finite family of nonempty partial cubes. Then
$\prod^{\square}_k V_k$ is harmonic-even if and only if every $V_k$ is
harmonic-even.
\end{theorem}

\begin{proof}[Proof sketch]
Fix $\langle k,i\rangle$. By Lemma~\ref{lem:prodcard} its balance equation reads
$\lvert\Semi{V_k}{i}{\tru}\rvert\,P = \lvert\Semi{V_k}{i}{\fls}\rvert\,P$ with
$P=\prod_{j\neq k}|V_j|$. Nonemptiness gives $P>0$, so this is equivalent to
balance of $i$ in $V_k$. Quantifying over all $\langle k,i\rangle$ yields the
claim; nonemptiness is used exactly at the cancellation of $P$.
\end{proof}

\begin{theorem}[Product Helly Law]\label{thm:prodhelly}
For a finite family of nonempty partial cubes, $\prod^{\square}_k V_k$ satisfies
the opposite-semicube Helly property if and only if every $V_k$ is harmonic-even.
\end{theorem}

\begin{proof}
Combine Theorem~\ref{thm:equiv} applied to the product with
Theorem~\ref{thm:prodbal}.
\end{proof}

\begin{corollary}[binary case: the classical statement]\label{cor:binary}
For nonempty partial cubes $G_1,G_2$, the Cartesian product $G_1\,\square\,G_2$
satisfies the opposite-semicube Helly property if and only if both $G_1$ and $G_2$
are harmonic-even.
\end{corollary}

\section{Algorithms}
Let $N=|V|$ and $d=|\alpha|$. \textbf{(A) Test:} count both semicubes per
coordinate and compare, $O(Nd)$; by Theorem~\ref{thm:equiv} this also decides the
Helly property. \textbf{(B) Parity pre-filter:} if $d\geq1$ and $N$ is odd, reject
in $O(1)$ (Theorem~\ref{thm:parity}). \textbf{(C) Product via factors:} test each
factor and combine by Theorem~\ref{thm:prodbal}, avoiding the exponentially large
product; cost $\sum_k O(|V_k|\,|\beta_k|)$. \textbf{(D) Canonical matching:} if
$V$ is antipodally closed, output the antipode as the per-cut matching
(Theorem~\ref{thm:mirror}).

\section{Discussion}
Harmonic-evenness is at once \emph{local} (Theorem~\ref{thm:equiv} reduces the
global matching condition to per-coordinate counts), \emph{canonical under
symmetry} (Theorem~\ref{thm:mirror}), \emph{parity-obstructed}
(Theorem~\ref{thm:parity}), and \emph{multiplicative}
(Theorems~\ref{thm:prodbal}--\ref{thm:prodhelly}). The unifying mechanism is that a
one-coordinate slice of a product is again a product with one factor replaced by a
semicube (Lemma~\ref{lem:slice}); the only analytic input is the cancellation of a
positive product of factor sizes, which is exactly where nonemptiness is required.
The canonical-matching route needs no nonemptiness, as it builds the bijection
directly from the antipode.

\section{Future work}
(1) An exact enumeration of coordinatewise systems of cut-representatives of a
family product, expected to factor as a product over factors with each
contribution raised to the power of the product of the remaining factor sizes.
(2) Antipodal closure as the exact obstruction to a single involutive matching of
every cut, separating ``balanced'' from ``symmetrically balanced.'' (3) Alphabet
independence: over a $q$-symbol alphabet with all $q$ fibers equinumerous, the
product balance law and its Helly reformulation persist, with the two-sided
matching replaced by a transitive family of bijections among the $q$ fibers and
the parity obstruction strengthened to divisibility of the vertex count by $q$.

\section{Conclusion}
Harmonic-evenness --- every cut halves the vertex set --- is equivalent to the
opposite-semicube Helly property and is governed by a single balance invariant that
is coordinate-local, canonically realized by antipodal symmetry, a parity
obstruction on the vertex count, and multiplicative across arbitrary finite
Cartesian products. In particular a Cartesian product of partial cubes satisfies
the opposite-semicube Helly property exactly when each factor is harmonic-even.

