from typing import List, Sequence, Tuple

Vertex = Tuple[bool, ...]


def semicube(V: Sequence[Vertex], i: int, b: bool) -> List[Vertex]:
    return [v for v in V if v[i] == b]


def is_harmonic_even(V: Sequence[Vertex]) -> bool:
    d = len(V[0]) if V else 0
    return all(len(semicube(V, i, True)) == len(semicube(V, i, False)) for i in range(d))


def path(n: int) -> List[Vertex]:
    d = n - 1
    return [tuple([True] * k + [False] * (d - k)) for k in range(n)]


if __name__ == "__main__":
    for n in range(2, 8):
        P = path(n)
        print(f"path({n}): |V|={len(P)} ({'even' if len(P)%2==0 else 'odd'}), "
              f"harmonic-even={is_harmonic_even(P)}")

"""Demo: product balance law -- product harmonic-even iff every factor is."""
from itertools import product as iproduct
from typing import List, Sequence, Tuple

Vertex = Tuple[bool, ...]


def semicube(V: Sequence[Vertex], i: int, b: bool) -> List[Vertex]:
    return [v for v in V if v[i] == b]


def is_harmonic_even(V: Sequence[Vertex]) -> bool:
    d = len(V[0]) if V else 0
    return all(len(semicube(V, i, True)) == len(semicube(V, i, False)) for i in range(d))


def cartesian_product(factors: Sequence[List[Vertex]]) -> List[Vertex]:
    return [tuple(x for v in combo for x in v) for combo in iproduct(*factors)]


def hypercube(d: int) -> List[Vertex]:
    return [tuple(bits) for bits in iproduct([False, True], repeat=d)]


def path(n: int) -> List[Vertex]:
    d = n - 1
    return [tuple([True] * k + [False] * (d - k)) for k in range(n)]


if __name__ == "__main__":
    cases = [[hypercube(2), hypercube(1)], [hypercube(1), path(3)], [path(3), path(3)]]
    for factors in cases:
        prod = cartesian_product(factors)
        each = [is_harmonic_even(f) for f in factors]
        print(f"factors HE={each}, product HE={is_harmonic_even(prod)}, "
              f"law holds={is_harmonic_even(prod) == all(each)}")

