from typing import List, Sequence, Tuple

Vertex = Tuple[bool, ...]


def harmonic_even_test(V: Sequence[Vertex]) -> bool:
    """Decide harmonic-evenness (equivalently the opposite-semicube Helly
    property) of a partial cube in O(|V| * d) time via per-coordinate tallies."""
    if not V:
        return True
    d = len(V[0])
    true_counts: List[int] = [0] * d
    for v in V:
        for i in range(d):
            if v[i]:
                true_counts[i] += 1
    n = len(V)
    # coordinate i balanced iff true_counts[i] == n - true_counts[i]
    return all(2 * c == n for c in true_counts)

from typing import List, Sequence, Tuple

Vertex = Tuple[bool, ...]


def _harmonic_even(V: Sequence[Vertex]) -> bool:
    if not V:
        return True
    d = len(V[0])
    n = len(V)
    counts = [0] * d
    for v in V:
        for i in range(d):
            if v[i]:
                counts[i] += 1
    return all(2 * c == n for c in counts)


def product_helly_via_factors(factors: Sequence[Sequence[Vertex]]) -> bool:
    """Decide the opposite-semicube Helly property of a Cartesian product WITHOUT
    materializing the product (whose size is the product of factor sizes). By the
    Product Balance Law the answer is the conjunction of the factor tests, provided
    every factor is nonempty. Cost: sum_k O(|V_k| * d_k)."""
    if any(len(f) == 0 for f in factors):
        raise ValueError("every factor must be nonempty for the product balance law")
    return all(_harmonic_even(f) for f in factors)
